grikod3 (Grikod, Gri Kod, Gray Code, GrayCode): binary ↔ grikod Mehmet Keçeci A Python library for converting binary numbers to Gray Code with ease. Tanım (Türkçe) Gri Kod: grikod3 İkili sayıları Gri Koda çevirir. Description (English) Gri Kod: grikod3 converts binary numbers to Gray Code. Kurulum (Türkçe) / Installation (English) Python ile Kurulum / Install with pip, conda, mamba pip install grikod3 -U python -m pip install -U grikod3 conda install bilgi::grikod3 -y mamba install bilgi::grikod3 -y - pip uninstall grikod3 -y + pip install -U grikod3 + python -m pip install -U grikod3 PyPI Test Kurulumu / Test Installation pip install -i https://test.pypi.org/simple/ grikod3 -U Github Master Kurulumu / GitHub Master Installation Terminal: pip install git+https://github.com/WhiteSymmetry/grikod3.git Jupyter Lab, Notebook, Visual Studio Code: !pip install git+https://github.com/WhiteSymmetry/grikod3.git # or %pip install git+https://github.com/WhiteSymmetry/grikod3.git Kullanım (Türkçe) / Usage (English) import grikod3 grikod3.__version__ import grikod3 grikod3.ikili_2_gri_kod("1010") import grikod3 def main(): # Binary numbers: ikili sayılar binary_numbers = ["0", "1", "10", "11", "100", "101", "1111"] for binary in binary_numbers: try: gray_code = grikod3.ikili_2_gri_kod(binary) print(f"Binary: İkili: {binary} -> Gri Kod: {gray_code}") except grikod3.InvalidBinaryError as e: print(f"İkili: {binary} -> Hata: {e}") if __name__ == "__main__": main() Binary: İkili: 0 -> Gri Kod: 0 Binary: İkili: 1 -> Gri Kod: 1 Binary: İkili: 10 -> Gri Kod: 11 Binary: İkili: 11 -> Gri Kod: 10 Binary: İkili: 100 -> Gri Kod: 110 Binary: İkili: 101 -> Gri Kod: 111 Binary: İkili: 1111 -> Gri Kod: 1000 #Input: 100 #Output example #000:000 #001:001 #010:011 #011:010 #100:110 #101:111 #110:101 #111:100 Graycode-Binary & Binary-Graycode from grikod2 import ikili_2_gri_kod grikod2.ikili_2_gri_kod("1010") from grikod3 import ikili_2_gri_kod, grikod2ikili, run_interactive_converter # Örnek kullanımlar: print(grikod2ikili("1011")) # Çıktı: "1101" (doğrulama: 1011 gri kodu 1101 ikiliğe denk gelir) print(grikod2ikili("0")) # "0" print(grikod2ikili("111")) # "101" from grikod3 import ikili_2_gri_kod, grikod2ikili, run_interactive_converter run_interactive_converter() import grikod3 def main(): print("🌟 Gri Kod Dönüştürücü - grikod3 Paketi ile") print("Geçerli bir ikili sayı girin (örneğin: 1101)") print("Çıkmak için 'q' yazın.
") while True: user_input = input("İkili sayı: ").strip() if user_input.lower() == 'q': print("👋 Çıkılıyor. İyi günler!") break try: gray_code = grikod3.ikili_2_gri_kod(user_input) print(f"✅ Gri Kod: {gray_code}
") except grikod3.InvalidBinaryError as e: print(f"❌ Giriş Hatası: {e}
") except Exception as e: print(f"⚠️ Beklenmeyen hata: {e}
") if __name__ == "__main__": main() import grikod3 if __name__ == "__main__": print("🚀 grikod3 Etkileşimli Moduna Hoş Geldiniz!") grikod3.run_interactive_converter() Development # Clone the repository git clone https://github.com/WhiteSymmetry/grikod3.git cd grikod3 # Install in development mode python -m pip install -ve . # Install package in development mode # Run tests pytest Notebook, Jupyterlab, Colab, Visual Studio Code !python -m pip install git+https://github.com/WhiteSymmetry/grikod3.git

